function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const A='#3d3830', B='#4a443c', Moss='#4a6b4a';
  px(0,0,32,32,A);
  for (let y=0;y<32;y+=4) for (let x=0;x<32;x+=4) {
    if (((x+y)/4)%2===0) px(x,y,4,4,B);
  }
  px(6,6,1,1,Moss); px(22,14,1,1,Moss); px(14,26,2,1,Moss);
}
